import time
import smbus2

ADS1115_I2C_ADDR = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

CONFIG_OS_SINGLE = 0x8000
CONFIG_MUX_AIN0P_GNDN = 0x4000
CONFIG_FSR_4V096 = 0x0200
CONFIG_MODE_SINGLE_SHOT = 0x0100
CONFIG_DATA_RATE_128SPS = 0x0080
CONFIG_COMP_QUE_DISABLE = 0x0003


def swap(a):
    return ((a & 0xff00) >> 8) | ((a & 0x00ff) << 8)


def readAdc(c, bus):
    config = (CONFIG_OS_SINGLE | CONFIG_MUX_AIN0P_GNDN | 
              CONFIG_FSR_4V096 | CONFIG_MODE_SINGLE_SHOT |
              CONFIG_DATA_RATE_128SPS | CONFIG_COMP_QUE_DISABLE | 
              (c << 12))
    bus.write_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, swap(config))
    while True:
        if (swap(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG)) & CONFIG_OS_SINGLE) == 0:
            return swap(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONVERSION))


if __name__ == "__main__":
    with smbus2.SMBus(1) as bus:
        try:
            while True:
                print("ADC 0:", readAdc(0, bus))
                print("ADC 1:", readAdc(1, bus))
                print("ADC 2:", readAdc(2, bus))
                print("ADC 3:", readAdc(3, bus))
                time.sleep(0.05)
        except KeyboardInterrupt:
            pass

