import spidev
import time
import signal
import sys

# SPI configuration for the MCP3002 ADC
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 50000

# Global variable to track program running state
running = True

def signal_handler(sig, frame):
    """Handles SIGTERM signal for graceful shutdown."""
    global running
    print("Shutting down gracefully...")
    running = False

def send_spi_command(spi, channel):
    """Sends SPI command to read from the specified channel."""
    command = [0x01, (0x08 + channel) << 4, 0x00]
    try:
        response = spi.xfer2(command)
        return response
    except IOError as e:
        print(f"SPI communication error: {e}")
        return None

def extract_10bit(response):
    """Extracts the 10-bit ADC value from the SPI response."""
    return ((response[1] & 0x03) << 8) | response[2]

def convert_to_weight(raw_data):
    """Converts raw ADC data to weight in kilograms."""
    return float(raw_data) * (5.0 / 1023.0)

class LoadCellReader:
    """Class to manage the load cell reading process."""

    def __init__(self, spi_bus, spi_device, spi_speed):
        """Initializes the LoadCellReader with SPI parameters."""
        self.spi = spidev.SpiDev()
        self.spi.open(spi_bus, spi_device)
        self.spi.max_speed_hz = spi_speed

    def read_raw_data(self, channel):
        """Reads raw data from the specified channel."""
        response = send_spi_command(self.spi, channel)
        if response:
            return extract_10bit(response)
        return None

    def close(self):
        """Closes the SPI connection."""
        self.spi.close()

def main():
    """Main function to read load cell data and print weight."""
    global running
    try:
        load_cell_reader = LoadCellReader(SPI_BUS, SPI_DEVICE, SPI_MAX_SPEED_HZ)
        while running:
            raw_data = load_cell_reader.read_raw_data(0)
            if raw_data is not None:
                weight = convert_to_weight(raw_data)
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if 'load_cell_reader' in locals():
            load_cell_reader.close()
        print("Program finished.")

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    main()

