#!/usr/bin/env python3

# Raspberry Pi 5 Voice-Controlled Greenhouse Automation System
# Author: Bard
# Date: October 26, 2023
# Description: This program controls a greenhouse environment using voice commands.
# It manages lighting, temperature monitoring, and camera capture.
# Hardware Requirements: Raspberry Pi 5, DHT11 Temperature Sensor, LED Strip, Camera Module.
# Software Dependencies: RPi.GPIO, time, datetime, speech_recognition, picamera2, adafruit_dht.

import RPi.GPIO as GPIO
import time
import datetime
import speech_recognition as sr
import picamera2
import adafruit_dht
import os
import signal
import sys

# GPIO Pin Definitions
LIGHT_PIN = 17
DHT_PIN = 4

# Global variables for state management
lights_on = False

# Initialize GPIO (simulated if RPi.GPIO is unavailable)
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    GPIO.output(LIGHT_PIN, GPIO.LOW)  # Ensure lights are off initially
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"Error initializing GPIO: {e}.  Running in simulated mode.")
    GPIO = None  # Disable GPIO if initialization fails

# Initialize DHT11 sensor (simulated if adafruit_dht is unavailable)
try:
    import board
    dht_device = adafruit_dht.DHT11(board.D4)
    print("DHT11 sensor initialized successfully.")
except ImportError:
    print("adafruit_dht library not found. Running in simulated temperature mode.")
    dht_device = None
except Exception as e:
    print(f"Error initializing DHT11 sensor: {e}. Running in simulated temperature mode.")
    dht_device = None

# Initialize Camera (simulated if picamera2 is unavailable)
try:
    camera = picamera2.Picamera2()
    camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
    camera.start()
    print("Camera initialized successfully.")
except ImportError:
    print("picamera2 library not found. Running in simulated camera mode.")
    camera = None
except Exception as e:
    print(f"Error initializing camera: {e}. Running in simulated camera mode.")
    camera = None

# Voice recognition setup
r = sr.Recognizer()
mic = sr.Microphone()

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Exiting program...")
    if GPIO:
        GPIO.cleanup()
    if camera:
        camera.close()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to read temperature from DHT11 sensor (simulated if sensor fails)
def read_temperature():
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT11 sensor returned None. Simulating temperature.")
                return simulate_temperature()
        except Exception as e:
            print(f"Error reading temperature from DHT11: {e}. Simulating temperature.")
            return simulate_temperature()
    else:
        return simulate_temperature()

# Function to simulate temperature readings
def simulate_temperature():
    return 20 + (time.time() % 10)  # Simulate temperature between 20 and 30

# Function to control the lights (simulated if GPIO is unavailable)
def turn_lights_on():
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        lights_on = True
        print("Lights turned ON.")
    else:
        print("Simulating lights turned ON.")

def turn_lights_off():
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        lights_on = False
        print("Lights turned OFF.")
    else:
        print("Simulating lights turned OFF.")

# Function to capture an image (simulated if camera is unavailable)
def take_picture():
    if camera:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        try:
            camera.capture_file(filename)
            print(f"Image captured and saved as {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
    else:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        print(f"Simulating image capture: greenhouse_{timestamp}.jpg")

# Main loop for voice recognition and command processing
def main():
    print("Greenhouse control system started. Say 'Greenhouse' to activate.")
    while True:
        try:
            with mic as source:
                r.adjust_for_ambient_noise(source)
                print("Say something!")
                audio = r.listen(source, timeout=5) # Added timeout to prevent indefinite blocking

            try:
                text = r.recognize_google(audio)
                print("You said: " + text)

                if "Greenhouse" in text.lower():
                    if "turn on the lights" in text.lower():
                        turn_lights_on()
                    elif "turn off the lights" in text.lower():
                        turn_lights_off()
                    elif "what is the temperature" in text.lower():
                        temperature = read_temperature()
                        print(f"The temperature is {temperature:.1f} degrees Celsius.")
                    elif "take a picture" in text.lower():
                        take_picture()
                    else:
                        print("Command not recognized.")

            except sr.UnknownValueError:
                print("Could not understand audio")
            except sr.RequestError as e:
                print(f"Could not request results from Google Speech Recognition service; {e}")

        except sr.WaitTimeoutError:
            pass # Ignore timeout errors
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

