import cv2
import pyzbar.pyzbar as pyzbar
import datetime
import logging
import configparser
import threading
import queue
import os
import time
import io

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'motion_threshold': '20',
        'redundancy_time_window': '5',
        'frame_buffer_size': '10',
        'cloud_upload_interval': '60',
        'log_level': 'INFO'
    }
}

# Initialize logging
logging.basicConfig(filename='inventory.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def load_config(config_file):
    """Loads configuration from the specified file."""
    config = configparser.ConfigParser()
    config.read(config_file)

    # Use default values if the config file is missing or incomplete
    for section, options in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        for option, value in options.items():
            if option not in config[section]:
                config[section][option] = value

    return config

def initialize_camera(camera_id):
    """Initializes a camera with the given ID."""
    try:
        camera_device = f'/dev/video{camera_id}'
        cap = cv2.VideoCapture(camera_device)
        if not cap.isOpened():
            raise Exception(f"Could not open camera {camera_id}")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        cap.set(cv2.CAP_PROP_FPS, 30)
        return cap
    except Exception as e:
        logging.error(f"Camera {camera_id} initialization failed: {e}")
        return None

def capture_frames(camera_id, frame_queue, stop_event):
    """Captures frames from a camera and puts them in a queue."""
    cap = initialize_camera(camera_id)
    if cap is None:
        return

    try:
        while not stop_event.is_set():
            ret, frame = cap.read()
            if not ret:
                logging.error(f"Camera {camera_id}: Failed to capture frame.")
                break
            frame_queue.put((camera_id, frame))
            time.sleep(0.033)  # Simulate frame rate
    except Exception as e:
        logging.error(f"Camera {camera_id}: Error capturing frames: {e}")
    finally:
        cap.release()
        logging.info(f"Camera {camera_id}: Camera released.")

def detect_motion(frame1, frame2, threshold):
    """Detects motion between two frames using frame differencing."""
    if frame1 is None or frame2 is None:
        return False

    diff = cv2.absdiff(frame1, frame2)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
    motion_pixels = cv2.countNonZero(thresh)
    return motion_pixels > threshold

def decode_qr_code(frame):
    """Decodes QR codes in a frame using pyzbar."""
    try:
        decoded_objects = pyzbar.decode(frame)
        return decoded_objects
    except Exception as e:
        logging.error(f"QR code decoding error: {e}")
        return []

def log_inventory(data, camera_id):
    """Logs inventory data to a file."""
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_message = f"{timestamp} - Camera {camera_id} - QR Code: {data}"
    try:
        with open('inventory.log', 'a') as f:
            f.write(log_message + '\n')
        logging.info(log_message)
    except Exception as e:
        logging.error(f"Error writing to inventory.log: {e}")
        try:
            with open('backup_inventory.log', 'a') as f:
                f.write(log_message + '\n')
            logging.warning(f"Wrote to backup_inventory.log: {log_message}")
        except Exception as e2:
            logging.error(f"Error writing to backup_inventory.log: {e2}")

def simulate_cloud_upload(upload_interval):
    """Simulates uploading inventory data to a cloud service."""
    while True:
        time.sleep(upload_interval)
        try:
            with open('inventory.log', 'r') as f:
                data = f.read()
            print(f"Simulating cloud upload: {data}")
            with open('inventory.log', 'w') as f:
                f.write("")  # Clear the file
            logging.info("Simulated cloud upload completed.")
        except FileNotFoundError:
            logging.warning("inventory.log not found, skipping upload.")
        except Exception as e:
            logging.error(f"Error during simulated cloud upload: {e}")

def main():
    """Main function to run the QR code inventory system."""
    config = load_config(CONFIG_FILE)

    # Extract configuration values
    motion_threshold = int(config['DEFAULT']['motion_threshold'])
    redundancy_time_window = float(config['DEFAULT']['redundancy_time_window'])
    frame_buffer_size = int(config['DEFAULT']['frame_buffer_size'])
    cloud_upload_interval = int(config['DEFAULT']['cloud_upload_interval'])
    log_level = config['DEFAULT']['log_level']

    # Set logging level
    logging.getLogger().setLevel(log_level)

    # Initialize frame buffers
    frame_buffers = {}
    for i in range(2):  # Two cameras
        frame_buffers[i] = []

    # Initialize cameras
    cameras = {}
    for i in range(2):
        cameras[i] = initialize_camera(i)
        if cameras[i] is None:
            logging.error(f"Camera {i} failed to initialize. Exiting.")
            return

    # Initialize stop events for threads
    stop_events = {}
    for i in range(2):
        stop_events[i] = threading.Event()

    # Initialize frame queues
    frame_queues = {}
    for i in range(2):
        frame_queues[i] = queue.Queue(maxsize=frame_buffer_size)

    # Start camera capture threads
    camera_threads = {}
    for i in range(2):
        camera_threads[i] = threading.Thread(target=capture_frames, args=(i, frame_queues[i], stop_events[i]))
        camera_threads[i].daemon = True  # Allow main thread to exit even if this thread is running
        camera_threads[i].start()

    # Start cloud upload thread
    cloud_thread = threading.Thread(target=simulate_cloud_upload, args=(cloud_upload_interval,))
    cloud_thread.daemon = True
    cloud_thread.start()

    # Last decoded QR code and timestamp for each camera
    last_decoded_qr_codes = {}
    last_decoded_timestamps = {}
    for i in range(2):
        last_decoded_qr_codes[i] = None
        last_decoded_timestamps[i] = 0

    last_motion_detection_time = {}
    for i in range(2):
        last_motion_detection_time[i] = time.time()

    watchdog_timer = {}
    for i in range(2):
        watchdog_timer[i] = threading.Timer(30, watchdog_restart, args=(i,))
        watchdog_timer[i].start()

    try:
        while True:
            for i in range(2):
                try:
                    camera_id, frame = frame_queues[i].get(timeout=0.1)

                    # Motion detection
                    if len(frame_buffers[i]) > 1:
                        if detect_motion(frame_buffers[i][-2], frame, motion_threshold):
                            if time.time() - last_motion_detection_time[i] > 1: # Debounce
                                last_motion_detection_time[i] = time.time()
                                logging.info(f"Motion detected by camera {i}")

                                # QR code decoding
