import board
import adafruit_dht

# Sensor configuration
SENSOR_PIN = board.D4  # GPIO4 (physical pin 7)

# Attempt limits
MAX_RETRIES = 5
RETRY_DELAY = 2  # seconds

def read_dht11_sensor(sensor):
    """
    Attempts to read temperature from the DHT11 sensor.
    Returns the temperature in Celsius or None on failure.
    """
    try:
        temperature_c = sensor.temperature
        if temperature_c is not None:
            return round(temperature_c, 1)
        else:
            return None
    except RuntimeError as error:
        print(f"DHT11 Error: {error.args[0]}")
        return None
    except Exception as error:
        print(f"Unexpected Error: {error}")
        return None

def main():
    """
    Main function to read DHT11 sensor and print the temperature.
    """
    dht_device = adafruit_dht.DHT11(SENSOR_PIN)

    for attempt in range(MAX_RETRIES):
        temperature = read_dht11_sensor(dht_device)

        if temperature is not None:
            print(f"Temperature: {temperature} °C")
            return  # Exit after successful read

        if attempt < MAX_RETRIES - 1:
            print(f"Attempt {attempt + 1}/{MAX_RETRIES}. Retrying in {RETRY_DELAY} seconds...")
            time.sleep(RETRY_DELAY)
        else:
            print("Error: Failed to read DHT11 sensor after multiple attempts.")
            return

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nScript interrupted. Exiting...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

