# -*- coding: utf-8 -*-
"""
Reads temperature and humidity from an Aosong Technology DHT20 sensor over I2C using a functional approach.

This module provides a class for interacting with the DHT20 sensor on a Raspberry Pi.
It uses the smbus2 library to communicate with the sensor over the I2C bus.
The code is structured in a functional style, with error handling and resource management.
"""

import time
import smbus2
import logging
from typing import Tuple

logger = logging.getLogger(__name__)

_DEFAULT_I2C_BUS = 1
_DEFAULT_I2C_ADDRESS = 0x38


def _calc_crc8(data: bytes) -> int:
    """Calculates the CRC-8 checksum for a given byte string."""
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = ((crc << 1) ^ 0x31) & 0xFF if crc & 0x80 else (crc << 1) & 0xFF
    return crc


def _read_register(bus: smbus2.SMBus, address: int, register: int, length: int) -> bytes:
    """Reads a specified number of bytes from a given register."""
    return bus.read_i2c_block_data(address, register, length)


def _write_register(bus: smbus2.SMBus, address: int, register: int, data: bytes) -> None:
    """Writes data to a given register."""
    bus.write_i2c_block_data(address, register, data)


def _init_sensor(bus: smbus2.SMBus, address: int) -> bool:
    """Initializes the DHT20 sensor."""
    time.sleep(0.5)  # Wait for sensor to stabilize after power-on
    status = _read_register(bus, address, 0x71, 1)[0]
    if (status & 0x18) != 0x18:
        logger.error("Sensor initialization failed.")
        return False
    return True


def _get_temperature_and_humidity(bus: smbus2.SMBus, address: int) -> Tuple[float, float, bool]:
    """Retrieves temperature and humidity from the sensor."""

    def _extract_data(raw_data: bytes) -> Tuple[int, int, int]:
        raw_h = int.from_bytes(raw_data[1:3], 'little')
        raw_t = int.from_bytes(raw_data[3:5], 'little')
        crc = raw_data[6]
        return raw_t, raw_h, crc

    def _convert_to_temperature_humidity(raw_t: int, raw_h: int) -> Tuple[float, float]:
        temperature = raw_t / 5242.88 - 50
        humidity = raw_h / 1048576 * 100
        return temperature, humidity

    def _verify_crc(raw_data: bytes, calculated_crc: int, received_crc: int) -> bool:
        return calculated_crc == received_crc

    for _ in range(5):  # Retry up to 5 times
        _write_register(bus, address, 0xAC, [0x33, 0x00])

        timeout = time.time() + 0.1 # 100ms timeout
        while True:
            status = _read_register(bus, address, 0x71, 1)[0]
            if (status & 0x80) == 0:
                break
            if time.time() > timeout:
                logger.warning("CRC Check Timeout - Retrying")
                continue #Retry

        data = _read_register(bus, address, 0x71, 7)

        raw_t, raw_h, received_crc = _extract_data(data)
        calculated_crc = _calc_crc8(data[:-1])

        if _verify_crc(data, calculated_crc, received_crc):
            temperature, humidity = _convert_to_temperature_humidity(raw_t, raw_h)
            return temperature, humidity, False
        else:
            logger.warning(f"CRC Error detected. Retrying. Calculated CRC: {calculated_crc}, Received CRC: {received_crc}")
            time.sleep(2) # Wait before retrying

    return None, None, True # Indicate failure after multiple retries


class DHT20:
    """Represents the DHT20 temperature and humidity sensor."""

    def __init__(self, bus_number: int = _DEFAULT_I2C_BUS, address: int = _DEFAULT_I2C_ADDRESS):
        """Initializes the DHT20 object."""
        try:
            self.bus = smbus2.SMBus(bus_number)
            if not _init_sensor(self.bus, address):
                raise Exception("DHT20 initialization failed")
        except Exception as e:
            logger.critical(f"Fatal initialization error: {e}")
            raise  # Re-raise to signal initialization failure

    def get_temperature_and_humidity(self) -> Tuple[float, float, bool]:
        """Retrieves temperature and humidity information."""
        return _get_temperature_and_humidity(self.bus, _DEFAULT_I2C_ADDRESS)

    def __del__(self):
        """Closes the I2C bus connection upon object destruction."""
        try:
            self.bus.close()
        except AttributeError:
            pass #bus might not be initialized if initialization failed
        except Exception as e:
            logger.error(f"Error closing I2C bus: {e}")

