import RPi.GPIO as GPIO
import time
import csv

# One-wire data pin for the DHT22 sensor (BCM numbering)
DHT_PIN = 4


def read_dht22():
    """Read temperature and humidity from the DHT22 sensor using RPi.GPIO."""
    # Send start signal by pulling the data pin low for 18ms
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    # Switch to input with pull-up and wait for the sensor response
    GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    time.sleep(0.00002)
    if GPIO.input(DHT_PIN) == GPIO.LOW:
        time.sleep(0.00008)
    else:
        return None, None
    # Read 40 data bits from the sensor
    data_bits = []
    for bit_index in range(40):
        pulse_start = time.time()
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.time() - pulse_start > 0.0001:
                return None, None
        pulse_end = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() - pulse_end > 0.00005:
                return None, None
        pulse_width = time.time() - pulse_start
        if pulse_width > 0.000026:
            data_bits.append(1)
        else:
            data_bits.append(0)
    # Combine bits into bytes and validate the checksum
    humidity_high = 0
    humidity_low = 0
    temperature_high = 0
    temperature_low = 0
    checksum = 0
    for byte_index in range(5):
        byte_value = 0
        for bit_index in range(8):
            byte_value <<= 1
            if data_bits[byte_index * 8 + bit_index]:
                byte_value |= 1
        if byte_index == 0:
            humidity_high = byte_value
        elif byte_index == 1:
            humidity_low = byte_value
        elif byte_index == 2:
            temperature_high = byte_value
        elif byte_index == 3:
            temperature_low = byte_value
        else:
            checksum = byte_value
    humidity = humidity_high + humidity_low / 10.0
    temperature = ((temperature_high & 0x7F) * 10 + temperature_low) / 10.0
    if temperature_high & 0x80:
        temperature = -temperature
    if checksum != (humidity_high + humidity_low + temperature_high + temperature_low) & 0xFF:
        return None, None
    return temperature, humidity


def main():
    """Read the DHT22 sensor and log readings to a CSV file."""
    GPIO.setmode(GPIO.BCM)
    try:
        while True:
            temperature, humidity = read_dht22()
