import time
import csv

# One-wire data pin for the DHT22 sensor (BCM numbering)
DHT_PIN = 4


def read_dht22():
    """Read temperature and humidity from the DHT22 sensor using RPi.GPIO."""
    # Send start signal by pulling the data pin low for 18ms
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    # Switch to input with pull-up and wait for the sensor response
    GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    time.sleep(0.00002)
    if GPIO.input(DHT_PIN) == GPIO.LOW:
        time.sleep(0.00008)
    else:
        return None, None
    # Read 40 data bits from the sensor
    data_bits = []
    for bit_index in range(40):
        pulse_start = time.time()
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.time() - pulse_start > 0.0001:
                return None, None
        pulse_end = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.time() - pulse_end > 0.00005:
                return None, None
        pulse_width = time.time() - pulse_start
        if pulse_width > 0.000026:
