# Raspberry Pi PWM-driven cooling fan controller using gpiozero
# Subcategory tag: PWM fan control from a temperature sensor
import time
import signal
import sys
import subprocess
from gpiozero import PWMOutputDevice

# PWM channel and frequency for the cooling fan
FAN_PIN = 14
PWM_FREQUENCY = 100


def read_cpu_temperature():
    """Read the Raspberry Pi CPU temperature in degrees Celsius."""
    # vcgencmd measure_temp returns a string like "temp=72.5'C"
    try:
        process = subprocess.run(["vcgencmd", "measure_temp"], capture_output=True, text=True, check=True)
        temperature_text = process.stdout
    except (subprocess.CalledProcessError, FileNotFoundError):
        # Fall back to a safe default temperature on failure
        print("Could not read temperature, using default 25C", file=sys.stderr)
        return 25.0
    return float(temperature_text.split("=")[1].split("'")[0])


def set_fan_speed(fan_device, temperature_value):
    """Set the fan duty cycle from a measured temperature."""
    # Map temperature bands to duty cycles
    if temperature_value > 70:
        fan_device.value = 100
    elif temperature_value > 60:
        fan_device.value = 85
    elif temperature_value > 50:
        fan_device.value = 70
    elif temperature_value > 40:
        fan_device.value = 50
    elif temperature_value > 32:
        fan_device.value = 25
    elif temperature_value > 25:
        fan_device.value = 15
    else:
        fan_device.value = 0


if __name__ == "__main__":
    # Create the PWM output device on the chosen GPIO pin
    cooling_fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQUENCY)
    try:
        # Continuously adjust the fan based on CPU temperature
        while True:
            current_temperature = read_cpu_temperature()
            set_fan_speed(cooling_fan, current_temperature)
            time.sleep(5)
    except (KeyboardInterrupt, SystemExit):
        # Stop the fan and exit cleanly on interrupt
        cooling_fan.close()
    except Exception as runtime_error:
        # Report any unexpected runtime failure
        print("Runtime error:", runtime_error, file=sys.stderr)
    finally:
        # Ensure the fan is stopped and GPIO released
        cooling_fan.close()

