# Environmental monitoring script for a Raspberry Pi 4 Model B
# Reads comma-separated temperature and humidity from a UART sensor
# Alerts when readings exceed safe thresholds
import serial
import time

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TEMP_LIMIT = 30.0
HUMID_LIMIT = 70.0


def open_serial_port(port, baud):
    """Open and configure the serial port for the environmental sensor."""
    # Configure the serial port with a timeout for read operations
    return serial.Serial(port, baud, timeout=1)


def parse_reading(raw_line):
    """Split and convert a comma-separated line into temperature and humidity."""
    # Split the line and convert each field to a float
    parts = raw_line.strip().split(",")
    if len(parts) != 2:
        return None, None
    return float(parts[0]), float(parts[1])


def check_thresholds(temperature, humidity):
    """Print an alert when temperature or humidity exceeds its limit."""
    # Evaluate both thresholds and emit a warning when crossed
    if temperature > TEMP_LIMIT:
        print("ALERT: temperature {0:.1f}C exceeds limit".format(temperature))
    if humidity > HUMID_LIMIT:
        print("ALERT: humidity {0:.1f}% exceeds limit".format(humidity))


if __name__ == "__main__":
    serial_connection = None
    try:
        # Open the serial port for the environmental sensor
        serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE)
        while True:
            try:
                # Read one line from the serial port
                raw_line = serial_connection.readline().decode("ascii", errors="replace")
                temperature, humidity = parse_reading(raw_line)
                if temperature is not None and humidity is not None:
                    print("Temperature {0:.1f}C humidity {1:.1f}%".format(temperature, humidity))
                    check_thresholds(temperature, humidity)
                time.sleep(1)
            except serial.SerialException as serial_error:
                # Handle a transient serial I/O error
                print("Serial error: {0}".format(serial_error))
            except ValueError as value_error:
                # Handle a malformed reading line
                print("Bad reading format: {0}".format(value_error))
            except Exception as unexpected_error:
                # Catch any other unexpected exception
                print("Unexpected error: {0}".format(unexpected_error))
    except serial.SerialException as init_error:
        # Report a failure to open the serial port
        print("Could not open serial port: {0}".format(init_error))
    finally:
        # Always close the serial connection when finished
        if serial_connection is not None:
            serial_connection.close()

