#!/usr/bin/env python3

# Filename: DHT20_demo.py
# Description: Reads temperature and humidity from a DHT20 sensor using I2C.
# Modified for functional style and improved error handling.

import time
import smbus2 as smbus
import signal
import sys

# Constants
I2C_BUS = 1
SENSOR_ADDRESS = 0x38
MEASUREMENT_DELAY = 0.08  # 80ms
READ_DELAY = 0.05  # 50ms

# Global variable for the I2C bus
bus = None

def init_i2c():
    """Initializes the I2C bus."""
    global bus
    try:
        bus = smbus.SMBus(I2C_BUS)
        return True
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return False

def read_register(register):
    """Reads a byte from the specified register."""
    try:
        return bus.read_byte_data(SENSOR_ADDRESS, register)
    except Exception as e:
        print(f"Error reading register 0x{register:02X}: {e}")
        return None

def write_register(register, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(SENSOR_ADDRESS, register, value)
        return True
    except Exception as e:
        print(f"Error writing to register 0x{register:02X}: {e}")
        return False

def read_data():
    """Reads 7 bytes of data from the sensor."""
    try:
        return [bus.read_byte_data(SENSOR_ADDRESS, i) for i in range(7)]
    except Exception as e:
        print(f"Error reading data: {e}")
        return None

def calculate_crc8(data):
    """Calculates the CRC8 checksum."""
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = (crc << 1) ^ 0x31
            else:
                crc = crc << 1
    return crc & 0xFF

def validate_reading(data):
    """Validates the reading based on the CRC checksum."""
    if data is None:
        return False
    calculated_crc = calculate_crc8(data[:-1])
    return data[-1] == calculated_crc

def initialize_sensor():
    """Initializes the sensor."""
    if not write_register(0x71, 0xBA):
        return False
    time.sleep(0.02)  # Wait 20ms
    if not read_register(0x71) & 0x08:
        print("Sensor initialization failed (status bit not set).")
        return False
    if not write_register(0x71, 0xBE) and not write_register(0x70, 0x08) and not write_register(0x70, 0x00):
        print("Sensor initialization failed (trigger sequence failed).")
        return False
    time.sleep(0.01)  # Wait 10ms
    return True

def get_temperature_humidity():
    """Gets the temperature and humidity from the sensor."""
    if not write_register(0x71, 0xAC) and not write_register(0x70, 0x33) and not write_register(0x70, 0x00):
        print("Measurement failed (trigger sequence failed).")
        return None, None
    time.sleep(MEASUREMENT_DELAY)
    data = read_data()
    if data is None or not validate_reading(data) or data[0] & 0x80: # Check busy bit
        print("Invalid reading or CRC error.")
        return None, None

    raw_temp = ((data[3] << 12) | (data[4] << 4) | (data[5] >> 4)) & 0xFFFFF
    raw_humid = ((data[5] & 0x0F) << 16) | (data[6] << 8) | data[7]

    temperature = (raw_temp / 1024.0) - 50.0
    humidity = (raw_humid / 1024.0) * 100.0

    fahrenheit = (temperature * 9/5) + 32

    return fahrenheit, humidity

def main():
    """Main function to read and print sensor data."""
    if not init_i2c():
        sys.exit(1)

    if not initialize_sensor():
        sys.exit(1)

    signal.signal(signal.SIGINT, lambda *args: sys.exit(0)) # Graceful exit on Ctrl+C

    try:
        while True:
            fahrenheit, humidity = get_temperature_humidity()
            if fahrenheit is not None and humidity is not None:
                print(f"Temperature: {fahrenheit:.2f} °F / {(temperature * 9/5 + 32):.2f} °C")
                print(f"Relative Humidity: {humidity:.2f} %")
            time.sleep(READ_DELAY)
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()

