# Hydroponics Control System - Sensor Monitoring
# Raspberry Pi 3 Model B+
# Uses gpiozero library to read digital input sensors

from gpiozero import DigitalInputDevice
import time
import signal
import sys

# Define GPIO pins for the sensors
SENSOR_PINS = [17, 27, 22]

# Define the idle state (HIGH) for each sensor
IDLE_STATE = True

# Initialize sensors
sensors = {}
for pin in SENSOR_PINS:
    try:
        sensors[pin] = DigitalInputDevice(pin, pull_up=True)
    except Exception as e:
        print(f"Error initializing sensor on pin {pin}: {e}")
        sys.exit(1)

# Define the polling interval in seconds
POLL_INTERVAL = 1

# Function to handle keyboard interrupt (Ctrl+C)
def signal_handler(sig, frame):
    print("Exiting program...")
    for pin in SENSOR_PINS:
        try:
            sensors[pin].close()
        except:
            pass
    sys.exit(0)

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop
print("Monitoring sensors on pins:", SENSOR_PINS)
print("Press Ctrl+C to exit.")

try:
    while True:
        for pin, sensor in sensors.items():
            try:
                if sensor.value != IDLE_STATE:
                    print(f"Response for sensor on pin {pin}")
            except Exception as e:
                print(f"Error reading sensor on pin {pin}: {e}")

        time.sleep(POLL_INTERVAL)

except Exception as e:
    print(f"An unexpected error occurred: {e}")

finally:
    print("Program finished.")

