import sys
import threading
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

class DOGServer:
    """
    A simple server for receiving and logging data using the DOGProtocol.
    """

    def __init__(self):
        """Initializes the server and GPIO."""
        self.log_file = None
        self.log_file_path = ""
        self.receive_thread = None
        self.server_running = False

    def start_server(self, log_file_path):
        """Starts the data logging server."""
        if self.server_running:
            print("Server already running.")
            return

        try:
            self.log_file_path = log_file_path
            with open(self.log_file_path, "a") as f:
                self.log_file = f
            self.server_running = True

            # Start the receive thread
            self.receive_thread = threading.Thread(target=self._receive_loop, daemon=True)
            self.receive_thread.start()

            print(f"Server started, logging to: {self.log_file_path}")

        except FileNotFoundError:
            print(f"Error: Log file not found: {self.log_file_path}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
