# Define a simple lexicon for sentiment analysis
vader_lexicon = {
    'good': 0.8, 'great': 0.7, 'happy': 0.6, 'love': 0.5, 'nice': 0.4,
    'bad': -0.8, 'terrible': -0.7, 'sad': -0.6, 'hate': -0.5, 'ugly': -0.4,
    'okay': 0.2, 'fine': 0.1, 'meh': -0.1, 'ok': 0.0, 'nothing': 0.0
}

def get_user_input():
    """Prompts the user for a sentence and returns it."""
    return input("Enter a sentence: ").strip()

def tokenize_sentence(sentence):
    """Tokenizes the sentence into lowercase words."""
    return sentence.lower().split()

def get_sentiment_score(sentence):
    """Calculates the average sentiment score of the sentence."""
    tokens = tokenize_sentence(sentence)
    total_score = 0
    for token in tokens:
        total_score += vader_lexicon.get(token, 0.0)  # Default to 0 if not found
    return total_score / len(tokens) if tokens else 0.0

def classify_sentiment(score):
    """Classifies the sentiment based on the score."""
    if score > 0.2:
        return "Positive"
    elif score < -0.2:
        return "Negative"
    else:
        return "Neutral"

def main():
    """Main function to run the sentiment analysis."""
    try:
        sentence = get_user_input()
        score = get_sentiment_score(sentence)
        sentiment = classify_sentiment(score)
        print(f"Sentiment: {sentiment}, Score: {score:.2f}")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        print("Sentiment analysis complete.")

if __name__ == "__main__":
    main()

