# web_led_control_functional.py
# A Flask web server that toggles an LED on a Raspberry Pi using gpiozero
# This version uses a functional style with a minimal state dictionary
import json
import logging
from typing import Callable, Any

import signal
import sys
from flask import Flask, render_template_string, make_response

# Configure logging for the web server
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

# GPIO pin connected to the LED (BCM numbering)
LED_GPIO_PIN = 17

# Minimal state dictionary shared between routes
app_state = {"led_state": False}


def initialize_led() -> None:
    """Initialize the LED object if running on a Raspberry Pi."""
    global app_state
    try:
        from gpiozero import LED
        led = LED(LED_GPIO_PIN)
        app_state["led"] = led
    except ImportError:
        # gpiozero not installed, likely not running on a Pi
        logging.info("gpiozero not available, skipping LED initialization")


def handle_shutdown(signum: int, frame: Any, led: "LED") -> None:
    """Release the LED resource on shutdown."""
    logging.info("Shutting down, releasing LED resource")
    if "led" in app_state:
        app_state["led"].close()
    sys.exit(0)


def render_index_page(led_state: bool) -> make_response:
    """Render the index page with ON/OFF links."""
    page_content = render_template_string(
        """<html><body>
        <h1>Raspberry Pi LED Control</h1>
        <p><a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a></p>
        {% if led_state %}
        <p>Current State: ON</p>
        {% else %}
        <p>Current State: OFF</p>
        {% endif %}
        </body></html>"""
    )
    return make_response(page_content)


def toggle_led(led: "LED", new_state: bool) -> bool:
    """Toggle the LED to the requested state and return the new state."""
    if "led" in app_state:
        led.value = new_state
    return new_state


def build_response(new_state: bool) -> make_response:
    """Build the HTML response for the new LED state."""
    status_text = "ON" if new_state else "OFF"
    return make_response(
        f"""<html><body>
        <h1>LED {status_text}</h1>
        <p><a href="/">Back to control</a></p>
        </body></html>"""
    )


def main() -> None:
    """Entry point: initialize hardware and run the Flask app."""
    app = Flask(__name__)
    initialize_led()

    # Register shutdown handler for clean resource release
    signal.signal(signal.SIGINT, lambda *args: handle_shutdown(signal.SIGINT, *args, app_state["led"]))
    signal.signal(signal.SIGTERM, lambda *args: handle_shutdown(signal.SIGTERM, *args, app_state["led"]))

    @app.route("/")
    def index_route() -> make_response:
        """Handle the main index route."""
        return render_index_page(app_state["led_state"])

    @app.route("/light_on")
    def light_on_route() -> make_response:
        """Handle the light_on route."""
        new_state = toggle_led(app_state["led"], True)
        app_state["led_state"] = new_state
        return build_response(new_state)

    @app.route("/light_off")
    def light_off_route() -> make_response:
        """Handle the light_off route."""
        new_state = toggle_led(app_state["led"], False)
        app_state["led_state"] = new_state
        return build_response(new_state)

    try:
        # Start the Flask development server on all interfaces
        app.run(host="0.0.0.0", port=8080, debug=False)
    except Exception as e:
        logging.error("Server error: %s", e)
    finally:
        # Ensure resources are released even on exceptions
        logging.info("Web server shutting down")
        if "led" in app_state:
            app_state["led"].close()


if __name__ == "__main__":
    main()

