import requests
import logging
import threading
import queue
import signal
import sys
from typing import Callable, Any, Dict, List, Tuple
from worker_K10CR1 import WK10CR1
from worker_DAC8532 import WDAC8532

class GenericHandler:
    """Handles subscriptions, unsubscriptions, and control commands for data streams."""

    def __init__(self, logger: logging.Logger, monitor_url: str = None):
        """Initializes the GenericHandler.

        Args:
            logger: Logger instance for logging.
            monitor_url: URL for the monitoring service.
        """
        self.logger = logger
        self.subscriptions: Dict[str, List[Dict[str, Any]]] = {}  # stream_filter: callback_info
        self.monitor_url = monitor_url
        self.subscriber_list: List[Dict[str, Any]] = []

    def handle_command(self, command: dict) -> str:
        """Processes commands related to subscriptions, unsubscriptions, and control.

        Args:
            command: A dictionary containing the command and its parameters.

        Returns:
            A message indicating the status of the command.
        """
        action = command.get('action')

        if not action:
            return "Error: No action specified."

        try:
            if action == 'SUBSCRIBE':
                return self._subscribe(command)
            elif action == 'UNSUBSCRIBE':
                return self._unsubscribe(command)
            elif action == 'UPDATE_KW':  # Update Keyword Arguments
                return self._update_kwargs(command)
            elif action == 'REMOVE_ALL_CBS':
                return self._remove_all_callbacks(command)
            elif action == 'RESET':
                return self._reset_channel(command)
            elif action == 'RESET_ALL':
                return self._reset_all_channels(command)
            elif action == 'MUTE':
                return self._mute_channel(command)
            elif action == 'UNMUTE':
                return self._mute_channel(command)
            elif action == 'MUTE_ALL':
                return self._mute_all_channels(command)
            elif action == 'UNMUTE_ALL':
                return self._unmute_all_channels(command)
            elif action == 'PAUSE':
                return self._pause_channel(command)
            elif action == 'RESTART':
                return self._restart_channel(command)
            elif action == 'PAUSE_ALL':
                return self._pause_all_channels(command)
            elif action == 'RESTART_ALL':
                return self._restart_all_channels(command)
            elif action == 'RESET_PWM': # Reset PWM values
                return self._reset_pwm_value(command)
            elif action == 'RESET_ALL_PWM':
                return self._reset_all_pwm_values(command)
            else:
                return "Error: Unknown action."

        except KeyError as e:
            return f"Error: Missing parameter: {e}"
        except Exception as e:
            self.logger.exception(f"Error processing command: {command}")
            return str(e)


    def _subscribe(self, command: dict) -> str:
        """Subscribes to a data stream.

        Args:
            command: A dictionary containing the stream filter and callback function.

        Returns:
            A message indicating whether the subscription was successful.
        """
        stream_filter = command['stream_filter']
        channel_id = command['id']
        callback_function = command['callback']  # Now directly stores the callable

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
        self.subscriptions[stream_filter].append({
            'callback': callback_function,
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False},
            'id': channel_id
        })

        self.subscriber_list.append({
            'stream_filter': stream_filter,
            'callback': callback_function,
            'kwargs': command.get('kwargs', {}),
            'state': {},
            'control': {'alert': True, 'pause': False},
            'id': channel_id
        })

        if self.monitor_url:
            try:
                requests.post(self.monitor_url + '/subscribe', json=self.subscriber_list[-1])
            except requests.exceptions.RequestException as e:
                self.logger.error(f"Error updating monitor: {e}")

        return f"Subscription successful to stream filter: {stream_filter}"


    def _unsubscribe(self, command: dict) -> str:
        """Unsubscribes from a data stream.

        Args:
            command: A dictionary containing the channel ID to unsubscribe.

        Returns:
            A message indicating whether the unsubscription was successful.
        """
        channel_id = command['id']
        for stream_filter, callbacks in list(self.subscriptions.items()):  # Use a copy to avoid modification during iteration
            for i, callback_info in enumerate(callbacks):
                if callback_info['id'] == channel_id:
                    callbacks.pop(i)
                    break  # Exit inner loop after removal


        for i, subscriber in enumerate(self.subscriber_list):
            if subscriber['id'] == channel_id:
                self.subscriber_list.pop(i)
                break

        if self.monitor_url:
            try:
                requests.post(self.monitor_url + '/unsubscribe', json=self.subscriber_list[:])  # Send remaining list
            except requests.exceptions.RequestException as e:
                self.logger.error(f"Error updating monitor: {e}")

        return f"Unsubscription successful for channel ID: {channel_id}"


    # ... (Other methods: _update_kwargs, _remove_all_callbacks, _mute_channel, etc.)
    # Implement these methods similarly with thorough error handling and logging.
