# Raspberry Pi 5 - Event-driven color sensor and image comparison

import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image
import threading

# Global flag to control the main loop
running = True

# I2C bus for the color sensor
i2c_bus = None

# TCS34725 color sensor object
color_sensor = None

# Function to handle Ctrl+C and SIGTERM signals
def signal_handler(sig, frame):
    """Handles Ctrl+C and SIGTERM signals for graceful shutdown."""
    global running
    print("Shutting down...")
    running = False

# Register the signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def initialize_i2c():
    """Initializes the I2C bus."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return True
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return False

def initialize_color_sensor():
    """Initializes the TCS34725 color sensor."""
    global color_sensor
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c_bus)
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
        return True
    except Exception as e:
        print(f"Error initializing color sensor: {e}")
        return False

def get_sensor_color_data():
    """Reads color data from the TCS34725 sensor."""
    try:
        red, green, blue, clear = color_sensor.color_rgb_bytes
        return (red, green, blue, clear)
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return (0, 0, 0, 0)

def find_dominant_image_color(image_path):
    """Finds the dominant color in an image."""
    try:
        img = Image.open(image_path)
        img = img.resize((100, 100))  # Reduce image size for faster processing
        colors = img.getcolors(10000)
        if colors:
            dominant_color = colors[0][1]
            return dominant_color
        else:
            return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main_loop():
    """Main loop to read sensor data and compare with image color."""
    while running:
        sensor_red, sensor_green, sensor_blue, _ = get_sensor_color_data()
        print(f"Sensor Color: R={sensor_red}, G={sensor_green}, B={sensor_blue}")

        dominant_image_color = find_dominant_image_color('image.jpg')
        print(f"Image Color: R={dominant_image_color[0]}, G={dominant_image_color[1]}, B={dominant_image_color[2]}")

        time.sleep(1)

if __name__ == "__main__":
    # Initialize I2C and the color sensor
    if initialize_i2c() and initialize_color_sensor():
        try:
            # Start the main loop in a separate thread
            main_thread = threading.Thread(target=main_loop)
            main_thread.daemon = True  # Allow the main thread to exit even if this thread is running
            main_thread.start()

            # Keep the main thread alive until a signal is received
            while running:
                time.sleep(0.1)

        except KeyboardInterrupt:
            print("Program interrupted by user.")
        finally:
            print("Cleaning up...")
            if i2c_bus:
                i2c_bus.deinit()
            print("Exiting.")
    else:
        print("Failed to initialize hardware. Exiting.")
        sys.exit(1)

