        except Exception as e:
            logger.error(f"Error turning on laser: {e}")
            raise

    def turn_off(self) -> None:
        """Turns the laser off."""
        try:
            self.laser.off()
            logger.info("Laser turned off")
        except Exception as e:
            logger.error(f"Error turning off laser: {e}")
            raise

    def close(self) -> None:
        """Releases the GPIO resource."""
        try:
            self.laser.close()
            logger.info("Laser resource released")
        except Exception as e:
            logger.error(f"Error releasing laser resource: {e}")



class AimingController:
    """Controls the servos and laser to aim at numbered blocks."""

    def __init__(self, laser_delay: float, short_delay: float):
        """Initializes the AimingController with delay parameters."""
        try:
            self.horizontal_servo = Servo(HORIZONTAL_SERVO_PIN)
            self.vertical_servo = Servo(VERTICAL_SERVO_PIN)
            self.laser_delay = laser_delay
            self.short_delay = short_delay
            logger.info("Servos initialized")
