                vertical_pos = VERTICAL_POSITIONS[block_number - 1]
            elif block_number == 11:
                horizontal_pos = HORIZONTAL_POSITIONS[10]  # Neutral
                vertical_pos = VERTICAL_POSITIONS[10]      # Neutral
            else:
                raise ValueError("Invalid block number for servo movement")

            self.horizontal_servo.value = horizontal_pos
            self.vertical_servo.value = vertical_pos
            time.sleep(self.short_delay)

            logger.debug(f"Servos moved to block {block_number}: Horizontal={horizontal_pos}, Vertical={vertical_pos}")

        except ValueError as ve:
            logger.error(ve)
            raise
        except Exception as e:
            logger.error(f"Error moving servos: {e}")
            raise

    def _turn_on_laser(self, laser_controller: LaserController) -> None:
        """Turns the laser on."""
