        """Turns the laser off."""
        try:
            laser_controller.turn_off()
        except Exception as e:
            logger.error(f"Error turning off laser: {e}")
            raise

    def close(self) -> None:
        """Releases the servo resources."""
        try:
            self.horizontal_servo.close()
            self.vertical_servo.close()
            logger.info("Servos released")
        except Exception as e:
            logger.error(f"Error releasing servo resources: {e}")


def main():
    """Main function to run the aiming routine."""
    try:
        laser_controller = LaserController(LASER_PIN)
        aiming_controller = AimingController(laser_delay=2, short_delay=0.5)

        # Define the blocks to aim at (1-based index)
        blocks_to_aim_at = [3, 5, 7, 10]

        aiming_controller.aim_at_blocks(blocks_to_aim_at, laser_controller)

    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if 'laser_controller' in locals():
            laser_controller.close()
        if 'aiming_controller' in locals():
            aiming_controller.close()


if __name__ == "__main__":
    main()

