# Hydroponics control system using plain English intent parsing on Raspberry Pi
# Uses gpiozero OutputDevice actuators for pump and light
# Demonstrates a simple natural language processing pipeline for home automation
import time
from gpiozero import OutputDevice

# BCM GPIO pins for the hydroponics actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize the gpiozero OutputDevice actuators
try:
    nutrient_pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
    grow_light = OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
except Exception as e:
    print("Error initializing actuators:", e)
    exit(1)


def parse_intent(phrase):
    """Parse a plain English phrase into a hydroponics control intent."""
    # Case-insensitive keyword matching for intent recognition
    lower_phrase = phrase.lower()
    if "turn the pump on" in lower_phrase:
        return "pump_on"
    if "turn the pump off" in lower_phrase:
        return "pump_off"
    if "switch the light" in lower_phrase:
        return "light_toggle"
    return None


def apply_intent(intent):
    """Apply a recognized intent to the hydroponics actuators."""
    # Map each intent to the corresponding actuator action
    if intent == "pump_on":
        nutrient_pump.on()
        print("Nutrient pump turned ON")
    elif intent == "pump_off":
        nutrient_pump.off()
        print("Nutrient pump turned OFF")
    elif intent == "light_toggle":
        grow_light.toggle()
        print("Grow light toggled")
    else:
        print("Unknown intent:", intent)


if __name__ == "__main__":
    # Test phrase list for the hydroponics control system
    test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    try:
        for phrase in test_phrases:
            intent = parse_intent(phrase)
            if intent:
                apply_intent(intent)
            else:
                print("No intent recognized:", phrase)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting hydroponics control system")
    except Exception as e:
        print("An error occurred:", e)
    finally:
        # Ensure all actuators are safely shut down on exit
        nutrient_pump.close()
        grow_light.close()

