# -*- coding: utf-8 -*-
"""
Raspberry Pi UPS Plus Demo Code (Object-Oriented)

This script demonstrates the functionalities of the UPS Plus module for Raspberry Pi using an object-oriented approach.
It reads various parameters such as voltage, current, temperature, and power status
and prints them to the console. It also shows how to set certain parameters like
protection voltage, sampling period, and shutdown countdown.

Advanced users can customize and develop this code to meet their specific needs.
"""

import time
import smbus2
import logging
from ina219 import INA219, DeviceRangeError

# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
DEVICE_BUS = 1
DEVICE_ADDR = 0x17
SUPPLY_INA219_ADDR = 0x40
BATTERY_INA219_ADDR = 0x45
PROTECT_VOLT = 3700
SAMPLE_TIME = 2
SUPPLY_SHUNT = 0.00725
BATTERY_SHUNT = 0.005

class INA219Sensor:
    """Represents an INA219 sensor."""

    def __init__(self, shunt_resistance, bus_number, device_address):
        try:
            self.sensor = INA219(shunt_resistance, busnum=bus_number, address=device_address)
            self.sensor.configure()
            logging.info(f"INA219 sensor initialized at address 0x{device_address:02X}")
        except Exception as e:
            logging.error(f"Failed to initialize INA219 at address 0x{device_address:02X}: {e}")
            self.sensor = None

    def read_data(self):
        """Reads and returns current, voltage, and power from the INA219 sensor."""
        if self.sensor is None:
            return None, None, None

        try:
            voltage = self.sensor.voltage()
            current = self.sensor.current()
            power = self.sensor.power()
            return current, voltage, power
        except DeviceRangeError:
            logging.warning("INA219 Device Range Error.")
            return None, None, None
        except Exception as e:
            logging.error(f"Error reading INA219 data: {e}")
            return None, None, None

class UPSPlus:
    """Represents the UPS Plus module."""

    def __init__(self, bus_number, device_address):
        try:
            self.bus = smbus2.SMBus(bus_number)
            self.device_address = device_address
            logging.info(f"UPS Plus module initialized on I2C bus {bus_number}")
        except Exception as e:
            logging.error(f"Failed to initialize UPS Plus module: {e}")
            self.bus = None

    def read_word_data(self, register):
        """Reads a 16-bit word from the specified register."""
        if self.bus is None:
            return None

        try:
            data = self.bus.read_word_data(self.device_address, register)
            return data
        except Exception as e:
            logging.error(f"Error reading data from register 0x{register:02X}: {e}")
            return None

    def read_byte_data(self, register):
        """Reads an 8-bit byte from the specified register."""
        if self.bus is None:
            return None

        try:
            data = self.bus.read_byte_data(self.device_address, register)
            return data
        except Exception as e:
            logging.error(f"Error reading data from register 0x{register:02X}: {e}")
            return None

    def write_byte_data(self, register, value):
        """Writes an 8-bit byte to the specified register."""
        if self.bus is None:
            return False

        try:
            self.bus.write_byte_data(self.device_address, register, value)
            return True
        except Exception as e:
            logging.error(f"Error writing data to register 0x{register:02X}: {e}")
            return False

    def get_supply_voltage(self):
        """Reads and returns the Raspberry Pi supply voltage."""
        data = self.read_word_data(1)
        if data is None:
            return None
        return self._convert_to_voltage(data)

    def _convert_to_voltage(self, data):
        """Converts raw data to voltage."""
        return lambda_voltage_mod * (data >> 8) + lambda_voltage_mod * (data & 0xff) / 1000

    def get_battery_voltage(self):
        """Reads and returns the battery voltage."""
        data = self.read_word_data(2)
        if data is None:
            return None
        return self._convert_to_voltage(data)

    def get_current(self):
        """Reads and returns the current."""
        data = self.read_word_data(3)
        if data is None:
            return None
        return lambda_current_mod * (data >> 8) + lambda_current_mod * (data & 0xff) / 1000

    def get_full_battery_voltage(self):
        """Reads and returns the full battery voltage."""
        data = self.read_word_data(4)
        if data is None:
            return None
        return self._convert_to_voltage(data)

    def get_battery_temperature(self):
        """Reads and returns the battery temperature."""
        data = self.read_word_data(5)
        if data is None:
            return None
        return (data >> 8) + lambda_temperature_mod * (data & 0xff) / 1000

    def get_protection_voltage(self):
        """Reads and returns the protection voltage."""
        data = self.read_word_data(6)
        if data is None:
            return None
        return self._convert_to_voltage(data)

    def get_sampling_period(self):
        """Reads and returns the sampling period."""
        data = self.read_byte_data(7)
        if data is None:
            return None
        return data & 0xff

    def get_power_state(self):
        """Reads and returns the power state."""
        data = self.read_byte_data(8)
        if data is None:
            return None
        return data & 0xff

    def get_shutdown_countdown(self):
        """Reads and returns the shutdown countdown."""
        data = self.read_word_data(9)
        if data is None:
            return None
        return (data >> 8) + lambda_shutdown_countdown_mod * (data & 0xff) / 1000

    def get_auto_recover_countdown(self):
        """Reads and returns the auto-recover countdown."""
        data = self.read_word_data(10)
        if data is None:
            return None
        return (data >> 8) + lambda_auto_recover_countdown_mod * (data & 0xff) / 1000

    def get_battery_remaining_capacity(self):
        """Reads and returns the battery remaining capacity."""
        data = self.read_word_data(19)
        if data is None:
            return None
        return (data >> 8) + lambda_battery_remaining_capacity_mod * (data & 0xff) / 1000

    def get_full_battery_remaining_capacity(self):
        """Reads and returns the full battery remaining capacity."""
        data = self.read_word_data(20)
        if data is None:
            return None
        return (data >> 8) + lambda_full_battery_remaining_capacity_mod * (data & 0xff) / 1000

    def get_battery_temperature_range(self):
        """Reads and returns the battery temperature range."""
        data = self.read_word_data(21)
        if data is None:
            return None
        return (data >> 8) + lambda_battery_temperature_range_mod * (data & 0xff) / 1000

    def get_battery_health(self):
        """Reads and returns the battery health."""
        data = self.read_byte_data(22)
        if data is None:
            return None
        return data & 0xff

    def get_power_state_machine(self):
        """Reads and returns the power state machine."""
        data = self.read_byte_data(23)
        if data is None:
            return None
        return data & 0xff

    def set_shutdown_countdown(self, seconds):
        """Sets the shutdown countdown in seconds."""
        try:
            data = (seconds // lambda_shutdown_countdown_mod) << 8
            self.bus.write_word_data(self.device_address, 9, data)
            logging.info(f"Shutdown countdown set to {seconds} seconds.")
            return True
        except Exception as e:
            logging.error(f"Error setting shutdown countdown: {e}")
            return False

    def set_sampling_period(self, period_ms):
        """Sets the sampling period in milliseconds."""
        if 0 <= period_ms <= 60000:
            try:
                self.bus.write_byte_data(self.device_address, 7, period_ms & 0xff)
                logging.info(f"Sampling period set to {period_ms} ms.")
                return True
            except Exception as e:
                logging.error(f"Error setting sampling period: {e}")
                return False
        else:
            logging.error("Invalid sampling period. Must be between 0 and 60000 ms.")
            return False

    def set_protection_voltage(self, voltage_mv):
        """Sets the protection voltage in millivolts."""
        try:
            data = self._convert_to_raw(voltage_mv)
            self.bus.write_word_data(self.device_address, 4, data)
            logging.info(f"Protection voltage set to {voltage_mv} mV.")
            return True
        except Exception as e:
            logging.error(f"Error setting protection voltage: {e}")
            return False

    def _convert_to_raw(self, voltage):
        """Converts voltage to raw data."""
        return int(voltage / lambda_voltage_mod)

    def close(self):
        """Closes the I2C bus."""
        if self.bus is not None:
            self.bus.close()
            logging.info("I2C bus closed.")

# Register Addresses (Moved to the UPSPlus class)
REG_SUPPLY_VOLTAGE = 1
REG_BATTERY_VOLTAGE = 2
REG_CURRENT = 3
REG_FULL_BATTERY_VOLTAGE = 4
REG_BATTERY_TEMPERATURE = 5
REG_PROTECTION_VOLTAGE = 6
REG_SAMPLING_PERIOD = 7
REG_POWER_STATE = 8
REG_SHUTDOWN_COUNTDOWN = 9
REG_AUTO_RECOVER_COUNTDOWN = 10
REG_BATTERY_REMAINING_CAPACITY = 19
REG_FULL_BATTERY_REMAINING_CAPACITY = 20
REG_BATTERY_TEMPERATURE_RANGE = 21
REG_BATTERY_HEALTH = 22
REG_POWER_STATE_MACHINE = 23

