    def __init__(self, shunt_resistance, bus_number, device_address):
        try:
            self.sensor = INA219(shunt_resistance, busnum=bus_number, address=device_address)
            self.sensor.configure()
            logging.info(f"INA219 sensor initialized at address 0x{device_address:02X}")
        except Exception as e:
            logging.error(f"Failed to initialize INA219 at address 0x{device_address:02X}: {e}")
            self.sensor = None

    def read_data(self):
        """Reads and returns current, voltage, and power from the INA219 sensor."""
        if self.sensor is None:
            return None, None, None

        try:
            voltage = self.sensor.voltage()
            current = self.sensor.current()
            power = self.sensor.power()
            return current, voltage, power
        except DeviceRangeError:
            logging.warning("INA219 Device Range Error.")
            return None, None, None
        except Exception as e:
            logging.error(f"Error reading INA219 data: {e}")
            return None, None, None

class UPSPlus:
    """Represents the UPS Plus module."""

    def __init__(self, bus_number, device_address):
        try:
            self.bus = smbus2.SMBus(bus_number)
            self.device_address = device_address
            logging.info(f"UPS Plus module initialized on I2C bus {bus_number}")
        except Exception as e:
            logging.error(f"Failed to initialize UPS Plus module: {e}")
            self.bus = None

