import smbus2
import contextlib

# I2C device driver for a Raspberry Pi using smbus2
class I2CDevice:
    """Wrapper around smbus2 that adds device verification and context management."""

    def __init__(self, address, bus_number=1):
        # Open the SMBus for the requested I2C bus number
        self.bus = smbus2.SMBus(bus_number)
        self.address = address
        # Probe the device so the driver can reject a missing device
        try:
            self.bus.read_byte(address)
        except Exception:
            raise RuntimeError("I2C device not present at address 0x%02X" % address)

    def write_byte(self, register, value):
        """Write a single byte to the given register."""
        # smbus2 expects a register and a value tuple
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as bus_error:
            raise RuntimeError("I2C write failed: %s" % bus_error)

    def read_byte(self, register):
        """Read a single byte from the given register."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as bus_error:
            raise RuntimeError("I2C read failed: %s" % bus_error)

    def close(self):
        """Close the underlying SMBus handle."""
        # Release the bus resource held by the driver
        self.bus.close()

    def __enter__(self):
        # Allow the device to be used as a context manager
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        # Close the bus automatically when the context exits
        self.close()

