from flask import Flask, Response, request, jsonify
import json
import time
import serial

app = Flask(__name__)
store = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]

def read_instrument(port="/dev/ttyUSB0", baudrate=9600, query='*IDN?\n'):
    """Read identification data from a SCPI instrument."""
    try:
        with serial.Serial(port, baudrate, timeout=1) as ser:
            ser.write(query.encode())
            time.sleep(0.1)  # Give the instrument time to respond
            response = ser.read(ser.in_waiting).decode('utf-8', errors='ignore') # Handle potential decode errors
            return response
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None

@app.route('/version')
def version():
    """Return the instrument's version information."""
    response = read_instrument()
    if response:
        return Response(response.replace('\n', '<br>'), mimetype='text/html')
    else:
        return Response("Instrument communication failed", mimetype='text/html', status=503)

@app.route('/getdata')
def get_data():
    """Return the entire store as JSON."""
    return jsonify(store)

@app.route('/getset/<int:item_id>')
def get_item(item_id):
    """Return a specific item from the store as JSON."""
    item = next((item for item in store if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found", status=404, mimetype='application/json')

@app.route('/getpost/<int:item_id>/<name>')
def post_item(item_id, name):
    """Add a new item to the store and return the updated store as JSON."""
    new_item = {
        "id": item_id,
        "name": name,
        "done": False
    }
